import json
BP={"refPath":"/Game/Gameplay/UI/V2/WBP_UITutorial.WBP_UITutorial"}
U="UMGToolSet.UMGToolSet."
O="editor_toolset.toolsets.object.ObjectTools."
A="editor_toolset.toolsets.asset.AssetTools."
def call(name,args):
    result=execute_tool(name,json.dumps(args));assert "returnValue" in result,(name,result)
    return result["returnValue"]
def ref(x):return x["refPath"] if isinstance(x,dict) else x
def update(obj,values):
    schema=json.loads(call(O+"list_properties",{"instance":obj}))
    norm=lambda x:x.lower().replace("_","")
    mapped={}
    for key,value in values.items():
        real=next((x for x in schema if norm(x)==norm(key)),None);assert real,(key,list(schema));mapped[real]=value
    call(O+"get_properties",{"instance":obj,"properties":list(mapped)})
    assert call(O+"set_properties",{"instance":obj,"values":json.dumps(mapped)})
def run():
    assert not call(A+"is_dirty",{"asset_path":"/Game/Gameplay/UI/V2/WBP_UITutorial"})
    before=call(U+"GetWidgets",{"widgetBlueprint":BP});nodes={x["widgetName"]:x for x in before["widgets"]}
    required=["TutorialV2Content","TutorialBodyScroll","TutorialV2Header","TutorialV2ActionShape","TutorialV2Body","TutorialV2Actions"]
    assert all(x in nodes for x in required)
    specs=[("TutorialV2ContentViewport","/Script/UMG.SizeBox","TutorialV2Content",0),("TutorialV2ScrollableContent","/Script/UMG.VerticalBox","TutorialBodyScroll",-1)]
    created=[]
    for name,cls,parent,index in specs:
        if name not in nodes:
            node=call(U+"AddWidget",{"widgetBlueprint":BP,"widgetClass":{"refPath":cls},"widgetDisplayName":name,"parentWidget":nodes[parent]["widget"],"childIndex":index})
            assert node and node["widgetName"]==name;nodes[name]=node;created.append(name)
    update(nodes["TutorialV2ContentViewport"]["widget"],{"minDesiredHeight":96})
    moves=[("TutorialV2Header","TutorialV2ScrollableContent",0),("TutorialV2ActionShape","TutorialV2ScrollableContent",1),("TutorialV2Body","TutorialV2ScrollableContent",2),("TutorialBodyScroll","TutorialV2ContentViewport",0),("TutorialV2Actions","TutorialV2Content",1)]
    for name,parent,index in moves:
        call(U+"MoveWidget",{"widgetBlueprint":BP,"widget":nodes[name]["widget"],"newParent":nodes[parent]["widget"],"childIndex":index})
    final=call(U+"GetWidgets",{"widgetBlueprint":BP});new={x["widgetName"]:x for x in final["widgets"]}
    for name,parent,index in moves:assert ref(new[name]["parent"])==ref(new[parent]["widget"]),(name,parent)
    for name in ("TutorialV2Header","TutorialV2ActionShape","TutorialV2Actions"):
        update(new[name]["slot"],{"padding":{"left":0,"top":12 if name=="TutorialV2Actions" else 0,"right":0,"bottom":0 if name=="TutorialV2Actions" else 10}})
    assert call(U+"CompileWidgetBlueprint",{"widgetBlueprint":BP})
    assert call(A+"save_assets",{"asset_paths":["/Game/Gameplay/UI/V2/WBP_UITutorial"]})
    assert all(name in new and ref(new[name]["widget"])==ref(node["widget"]) for name,node in nodes.items())
    return {"created":created,"oldCount":len(before["widgets"]),"newCount":len(final["widgets"]),"preservedObjects":True,"footerPinned":True}
